export const getGetWebhooksUrl = (params?: GetWebhooksParams) => {
  const normalizedParams = new URLSearchParams();
  const deepObjectEntries: string[] = [];

  Object.entries(params || {}).forEach(([key, value]) => {
    const deepObjectParameters = ["fields", "page"];

    if (typeof value === "object" && value !== null && !Array.isArray(value) && deepObjectParameters.includes(key)) {
      Object.entries(value).forEach(([subKey, subValue]) => {
        if (subValue !== undefined) {
          deepObjectEntries.push(
            encodeURIComponent(key) +
              "[" +
              encodeURIComponent(subKey) +
              "]=" +
              (subValue === null ? "null" : encodeURIComponent(String(subValue)))
          );
        }
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = [normalizedParams.toString(), deepObjectEntries.join("&")].filter(Boolean).join("&");

  return stringifiedParams.length > 0 ? `/api/oauth2/v2/webhooks?${stringifiedParams}` : `/api/oauth2/v2/webhooks`;
};

/** @summary Get webhooks */
export const getWebhooks = async (params?: GetWebhooksParams, options?: RequestInit): Promise<getWebhooksResponse> => {
  const res = await fetch(getGetWebhooksUrl(params), {
    ...options,
    method: "GET"
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getWebhooksResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as getWebhooksResponse;
};

