export const getCreateWebhookUrl = () => {
  return `/api/oauth2/v2/webhooks`;
};

/** @summary Create webhook */
export const createWebhook = async (
  createWebhookBody: CreateWebhookBody,
  options?: RequestInit
): Promise<createWebhookResponse> => {
  const getHeaders = (h?: NonNullable<RequestInit["headers"]>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string])
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  const res = await fetch(getCreateWebhookUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(createWebhookBody)
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: createWebhookResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as createWebhookResponse;
};
